NAV_PATTERN = re.compile(
    r'<div class="container-fluid sticky-top(?: site-header)?">.*?</nav>\s*</div>\s*</div>',
    re.DOTALL,
)
CLUSTER_NAV_PATTERN = re.compile(
    r'<header class="cluster-header"><div class="container-fluid sticky-top">.*?</header>',
    re.DOTALL,
)


FOOTER_PATTERN = re.compile(r'<footer id="footer".*?</footer>', re.DOTALL)
CLUSTER_FOOTER_PATTERN = re.compile(r'<footer class="cluster-footer".*?</footer>', re.DOTALL)

def main() -> None:
    updated = 0
    for page in ROOT.glob("*.html"):
        source = page.read_bytes().decode("utf-8")
        result, nav_count = NAV_PATTERN.subn(MENU, source, count=1)
        if not nav_count:
            result, nav_count = CLUSTER_NAV_PATTERN.subn(MENU, source, count=1)
        result, footer_count = FOOTER_PATTERN.subn(FOOTER, result, count=1)
        if not footer_count:
            result, footer_count = CLUSTER_FOOTER_PATTERN.subn(FOOTER, result, count=1)
        if nav_count and "bootstrap.bundle.min.js" not in result:
            result = result.replace("</body>", '<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.0.0/dist/js/bootstrap.bundle.min.js" defer></script></body>', 1)
        if result != source:
            page.write_bytes(result.encode("utf-8"))
            updated += 1
    print(f"Updated site chrome in {updated} pages")

if __name__ == "__main__":
    main()
